command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "a68626830efb6e251c43d4667b4cae93bb35885c") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "main fast-forward failed" }
python -X utf8 tests\winui\test_remote_windows_task_contract.py
if ($LASTEXITCODE -ne 0) { throw "focused remote workflow contract failed" }
git diff --check HEAD^..HEAD
if ($LASTEXITCODE -ne 0) { throw "main diff check failed" }
Write-Host "VALIDATION_CHURN_GUARDS_RUNTIME_PASS"
